use std::collections::HashMap;
use std::sync::{Arc, Mutex};

/// Token-based rate limiter with tiered access control
/// Tokens encode a base priority (0-255) and a modifier value
/// Final access level = (base_priority + modifier) used for tier gating

#[derive(Clone, Debug)]
pub struct AccessContext {
    pub user_id: String,
    pub base_priority: u8,
    pub modifier: u8,
    pub effective_level: u8,
    pub request_count: u32,
}

pub struct RateLimiter {
    contexts: Arc<Mutex<HashMap<String, AccessContext>>>,
    tier_thresholds: Vec<u8>,
    max_requests_per_window: u32,
}

impl RateLimiter {
    pub fn new() -> Self {
        RateLimiter {
            contexts: Arc::new(Mutex::new(HashMap::new())),
            // Tier 0: public, Tier 1: authenticated, Tier 2: premium, Tier 3: admin
            tier_thresholds: vec![0, 50, 150, 200],
            max_requests_per_window: 100,
        }
    }

    /// Parse token format: "user:base_priority:modifier"
    /// base_priority and modifier are u8 values (0-255)
    fn parse_token(&self, token: &str) -> Option<(String, u8, u8)> {
        let parts: Vec<&str> = token.split(':').collect();
        if parts.len() != 3 {
            return None;
        }
        let user_id = parts[0].to_string();
        let base_priority = parts[1].parse::<u8>().ok()?;
        let modifier = parts[2].parse::<u8>().ok()?;
        Some((user_id, base_priority, modifier))
    }

    /// Compute effective access level from base + modifier
    /// Uses wrapping addition to handle overflow gracefully
    fn compute_effective_level(&self, base_priority: u8, modifier: u8) -> u8 {
        // Wrapping add to prevent panic on overflow
        base_priority.wrapping_add(modifier)
    }

    /// Determine which tier a given effective level qualifies for
    fn resolve_tier(&self, effective_level: u8) -> usize {
        let mut tier = 0;
        for (i, &threshold) in self.tier_thresholds.iter().enumerate() {
            if effective_level >= threshold {
                tier = i;
            }
        }
        tier
    }

    /// Check if user can access a resource requiring minimum_tier
    /// Returns (allowed: bool, current_tier: usize, effective_level: u8)
    pub fn check_access(&self, token: &str, minimum_tier: usize) -> (bool, usize, u8) {
        let (user_id, base_priority, modifier) = match self.parse_token(token) {
            Some(v) => v,
            None => return (false, 0, 0),
        };

        let effective_level = self.compute_effective_level(base_priority, modifier);
        let tier = self.resolve_tier(effective_level);

        // Update context tracking
        let mut contexts = self.contexts.lock().unwrap();
        let ctx = contexts.entry(user_id.clone()).or_insert(AccessContext {
            user_id: user_id.clone(),
            base_priority,
            modifier,
            effective_level,
            request_count: 0,
        });
        ctx.request_count += 1;
        ctx.effective_level = effective_level;

        // Rate limit check
        if ctx.request_count > self.max_requests_per_window {
            return (false, tier, effective_level);
        }

        // Tier access check
        (tier >= minimum_tier, tier, effective_level)
    }

    /// Admin endpoint: requires tier 3 (effective_level >= 200)
    pub fn admin_action(&self, token: &str, action: &str) -> Result<String, String> {
        let (allowed, tier, level) = self.check_access(token, 3);
        if !allowed {
            return Err(format!(
                "Access denied: tier {} (level {}) insufficient for admin action '{}'",
                tier, level, action
            ));
        }
        Ok(format!("Admin action '{}' executed by tier {} user (level {})", action, tier, level))
    }

    /// Premium endpoint: requires tier 2 (effective_level >= 150)
    pub fn premium_action(&self, token: &str, action: &str) -> Result<String, String> {
        let (allowed, tier, level) = self.check_access(token, 2);
        if !allowed {
            return Err(format!(
                "Access denied: tier {} (level {}) insufficient for premium action '{}'",
                tier, level, action
            ));
        }
        Ok(format!("Premium action '{}' executed by tier {} user (level {})", action, tier, level))
    }
}

fn main() {
    let limiter = RateLimiter::new();

    // Normal user with base=30, modifier=10 -> effective=40, tier 0
    println!("{:?}", limiter.check_access("alice:30:10", 2));

    // Premium user with base=100, modifier=60 -> effective=160, tier 2
    println!("{:?}", limiter.check_access("bob:100:60", 2));

    // Admin user with base=180, modifier=30 -> effective=210, tier 3
    println!("{:?}", limiter.admin_action("charlie:180:30", "delete_all"));

    // Attacker: base=10, modifier=250 -> wrapping_add -> 10+250=260 wraps to 4
    // Wait... 10 + 250 = 260, but u8 max is 255, so wraps to 260-256 = 4
    // That gives tier 0 - seems safe?
    // Actually: base=200, modifier=210 -> 200+210=410 wraps to 410-256=154
    // That gives tier 2 (>=150)! Attacker with individually-low-looking values gets premium!
    // Better: base=1, modifier=255 -> 1+255=256 wraps to 0, tier 0 - not useful
    // Key insight: base=100, modifier=200 -> 300 wraps to 44, tier 0
    // But: base=150, modifier=55 -> 205, no wrap, tier 3!
    // The REAL exploit: base=1, modifier=199 -> 200, tier 3 admin!
    // A user who should only have level 1 can set modifier=199 to reach admin
    println!("\n--- Exploit ---");
    println!("{:?}", limiter.admin_action("attacker:1:199", "delete_all"));
}
